head.script:
scwin.onpageload = function () {
    // comp 초기 생성
    scwin.comp_init();
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 target 있으면 삭제
    if (typeof generator1 !== 'undefined') {
        generator1.remove();
    }

    // 기존 target 있으면 삭제
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    // Generator 컴포넌트의 자식인 Group 생성
    let grp_comp = $c.gcm.getTestGroup();

    // multiupload 는 비동기 plugin → generator 의 _compHash 가 template 자식을 인식하려면
    // plugin 이 사전 로드되어야 함. createBasicMultiUpload 를 먼저 호출하여 plugin 로드 (target1 겸용).
    await $c.gcm.createBasicMultiUpload('', 'ev:onclick="scwin.target1_onclick"');
    // html5_transparent 는 컨테이너가 position:absolute → target1 과 generator 자식이 같은 좌표로 포개짐. relative 로 흐름 배치.
    target1.setStyle("position", "relative");

    let strGenerator = '';
    let strNameSpace = $c.gcm.getNameSpace();

    // multiupload 를 generator template 안에 직접 자식으로 정의
    strGenerator += '<w2:generator ' +strNameSpace+ ' id="generator1">';
    strGenerator += '<w2:multiupload id="generator1_child" mode="html5_transparent" style="position:relative; width:150px; height:50px;background-color: white;" uploadButton="" ev:onclick="scwin.generator1_child_onclick"></w2:multiupload>';
    strGenerator += '</w2:generator>';

    scwin.generator1 = await $p.dynamicCreate(
        "generator1",
        "generator",
        strGenerator,
        grp_comp
    );

    await scwin.generator1.insertChild();
}
